from collections import defaultdict

def shiftset(S,t): return {(r+t[0],c+t[1]) for r,c in S}
def inbounds(p,t):
  return all(1<=r+t[0]<=26 and 1<=c+t[1]<=26 for r,c in p['C']|p['M'])
def compatible(a,ta,b,tb):
  # color cells cannot overlap anything from another part; markers may overlap markers
  ca=shiftset(parts[a]['C'],ta); ma=shiftset(parts[a]['M'],ta)
  cb=shiftset(parts[b]['C'],tb); mb=shiftset(parts[b]['M'],tb)
  return not (ca & (cb|mb) or cb & ma)
def paircands(a,b):
  # apply shifts relative to b at (0,0), return shift for a, where marker overlap
  A=parts[a]['M']; B=parts[b]['M']
  ts=set((br-ar,bc-ac) for ar,ac in A for br,bc in B) # A+t=B
  out=[]
  for t in ts:
    n=len(shiftset(A,t)&B)
    if n and inbounds(parts[a],t) and compatible(a,t,b,(0,0)):
      out.append((n,t))
  return sorted(out,reverse=True)
for a in parts:
  for b in parts:
    if a<b:
      x=paircands(a,b)
      if x:
       print(a,b,x)

def shift_candidates_to_markers(pname, placed_mark_coords):
  return { (rr-r,cc-c) for r,c in parts[pname]['M'] for rr,cc in placed_mark_coords }
def colors_nonoverlap(name,t,placements):
  C=shiftset(parts[name]['C'],t); M=shiftset(parts[name]['M'],t)
  for other,ot in placements.items():
    oc=shiftset(parts[other]['C'],ot); om=shiftset(parts[other]['M'],ot)
    if C & (oc|om) or M & oc:
      return False
  return True
def transformed_marks(name,t): return shiftset(parts[name]['M'],t)
anchor={'4':(0,0)}
