for n in parts:
  if n=='4':continue
  cs=shift_candidates_to_markers(n,anchor_ms)
  valid=[t for t in cs if inbounds(parts[n],t) and colors_nonoverlap(n,t,anchor)]
  scored=sorted([(len(transformed_marks(n,t)&anchor_ms),t) for t in valid],reverse=True)
  print(n,scored)

